package com.muthumol.player.dummy;
import java.util.*;import org.json.*;import java.net.*;import java.io.*;
final class SkipSegments {
 static final class Segment{final long start,end;final String kind;Segment(long s,long e,String k){start=s;end=e;kind=k;}}
 static List<Segment> parse(JSONObject response){List<Segment> result=new ArrayList<>();for(String kind:new String[]{"intro","recap","credits"}){JSONArray values=response.optJSONArray(kind);if(values==null)continue;for(int i=0;i<values.length();i++){JSONObject v=values.optJSONObject(i);if(v==null)continue;long start=v.optLong("start_ms",0),end=v.isNull("end_ms")?-1:v.optLong("end_ms",-1);if(start>=0&&(end<0||end>start))result.add(new Segment(start,end,kind));}}result.sort(Comparator.comparingLong(s->s.start));return result;}
 static List<Segment> fetch(Movie movie)throws Exception{MediaTitle title=MediaTitle.parse(movie.title);String imdb=MsoneSubtitles.imdb(title);if(imdb.isEmpty())return Collections.emptyList();String url="https://api.theintrodb.org/v3/media?imdb_id="+imdb+(title.episodic()?"&season="+title.season+"&episode="+title.episode:"");return parse(new JSONObject(new String(get(url),"UTF-8")));}
 static byte[] get(String url)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(url).openConnection();c.setConnectTimeout(5000);c.setReadTimeout(7000);c.setInstanceFollowRedirects(false);c.setRequestProperty("User-Agent","TGstream/6.2");try{if(c.getResponseCode()!=200)return "{}".getBytes("UTF-8");try(InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){if(out.size()+n>262144)throw new IOException("Skip timing response too large");out.write(b,0,n);}return out.toByteArray();}}finally{c.disconnect();}}
 static Segment active(List<Segment> list,long position,long duration){for(Segment s:list){long end=s.end>=0?s.end:duration;if(end>s.start&&position>=s.start&&position<end-1000)return s;}return null;}
}
